    if order['reefer']: t += transfers[terminal]['reefer_extra_minutes']
    if order['hazmat']: t += transfers[terminal]['hazmat_extra_minutes']
    return t

max_late=config['max_lateness_minutes']

def enumerate_paths(order, scen=None):
