                    continue
            if lane['destination'] in visited and lane['destination'] "'!= order['"'destination']:
                continue
            if arr > order['due_minute'] + max_late: continue
            dfs(lane['destination'], arr, path+[lid], visited|{lane['destination']})
    dfs(order['origin'], order['ready_minute'], [], {order['origin']})
    return results

for o in orders:
    rp=enumerate_paths(o)
    counts=[len(enumerate_paths(o,s)) for s in scenarios]
    print(o['order_id'], len(rp), counts, 'max', max(counts))
print('total reserved', sum(len(enumerate_paths(o)) for o in orders))
print('total scenario paths', sum(sum(len(enumerate_paths(o,s)) for s in scenarios) for o in orders))
